package com.vocast.app;
import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;
public class NovelMergePerformance {
 public static void main(String[] args)throws Exception{File root=new File("artifacts/novel/e2e");JSONObject manifest=new JSONObject(new String(AudioFiles.read(new File(root,"library.json"),1024*1024),StandardCharsets.UTF_8));String id=manifest.getJSONArray("books").getJSONObject(0).getJSONArray("chapters").getJSONObject(1).getString("id");JSONObject chapter=new SnapshotStore(root).loadChapter(id);JSONArray segments=chapter.getJSONArray("segments");List<String> ids=new ArrayList<>();for(int i=0;i<segments.length();i++)ids.add(segments.getJSONObject(i).getString("audio"));long start=System.nanoTime();JSONObject result=new AudioFiles(root).merge(ids);if(!result.getString("id").equals(chapter.getString("audio")))throw new AssertionError("Native merge differs from verified output");result.put("elapsedMs",(System.nanoTime()-start)/1e6).put("heapLimitBytes",Runtime.getRuntime().maxMemory()).put("pass",true);try(FileOutputStream out=new FileOutputStream("artifacts/novel/performance/merge-report.json")){out.write(result.toString(2).getBytes(StandardCharsets.UTF_8));}System.out.println(result.toString(2));}
}
